import type { Student } from './student-model';
import type { Teacher } from './teacher-model';

export interface QuizHistory {
  /**
   * @displayName Quiz History
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Quiz Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  quizname: string;
  /**
   * @displayName Date Taken
   */
  datetaken?: string;
  /**
   * @displayName Score Percentage
   */
  scorepercentage?: number;
  /**
   * @displayName Student Name
   */
  studentname?: Pick<Student, 'id' | 'firstname'>;
  /**
   * @displayName Teacher Name
   */
  teachername?: Pick<Teacher, 'id' | 'fullname'>;
}

export const _QuizHistory = 'QuizHistory' as const;